     1|/**
     2| * IVX Self-Hosted Senior Developer Worker — removes the Rork dependency as the
     3| * code EXECUTOR.
     4| *
     5| * Rork is no longer required to run a development task. Instead:
     6| *   1. IVX IA (or the owner-gated API) submits an owner-approved task to this
     7| *      worker's durable job QUEUE.
     8| *   2. A single-flight WORKER drains the queue and runs the real end-to-end
     9| *      execution pipeline already implemented in `ivx-senior-developer-runtime`:
    10| *      repo read → file create/modify → tests → typecheck → build → commit →
    11| *      push → Render deploy → poll deploy → verify /health + /version.
    12| *   3. Every job's verifiable result is recorded in a durable PROOF LEDGER
    13| *      (Supabase-backed, survives Render's diskless restarts; in-memory fallback
    14| *      for local/test).
    15| *
    16| * This module owns ONLY the orchestration that did not exist before (queue,
    17| * worker loop, ledger). It reuses the proven execution primitives so there is
    18| * no duplicated GitHub/Render/test logic and no fabricated proof.
    19| *
    20| * Security:
    21| *   - Owner approval is enforced at the API boundary BEFORE a job is enqueued;
    22| *     the approval contract is stored on the job. The worker refuses to run a
    23| *     job whose `ownerApproved` flag is not true.
    24| *   - No secret values are ever stored on a job or in the ledger.
    25| */
    26|import { randomUUID } from 'node:crypto';
    27|import {
    28|  appendDurableEvent,
    29|  isDurableStoreConfigured,
    30|  readDurableJson,
    31|  writeDurableJson,
    32|} from './ivx-durable-store';
    33|import {
    34|  IVX_GIT_DEPLOY_CONFIRM_TEXT,
    35|  IVX_SAFE_PATCH_CONFIRM_TEXT,
    36|  runIVXSeniorDeveloperTask,
    37|  verifyLiveCommitMatch,
    38|  type IVXSeniorDeveloperApprovedActionContract,
    39|  type IVXSeniorDeveloperRunProof,
    40|} from './ivx-senior-developer-runtime';
    41|
    42|export const IVX_SENIOR_DEV_WORKER_MARKER = 'ivx-senior-developer-worker-2026-06-16';
    43|
    44|/** Repo-relative keys so the durable store derives stable doc keys. */
    45|const QUEUE_FILE = 'logs/audit/senior-developer-worker/queue.json';
    46|const LEDGER_FILE = 'logs/audit/senior-developer-worker/proof-ledger.json';
    47|
    48|const MAX_QUEUE_RETAINED = 200;
    49|const MAX_LEDGER_RETAINED = 200;
    50|
    51|export type IVXWorkerJobStatus = 'queued' | 'running' | 'completed' | 'failed' | 'blocked';
    52|
    53|/** Owner-approved task accepted by the worker. Never carries secret values. */
    54|export type IVXWorkerJobInput = {
    55|  goal: string;
    56|  /** Owner approval was verified at the API boundary before enqueue. */
    57|  ownerApproved: boolean;
    58|  /** Apply the prepared safe code patch. */
    59|  approvePatch: boolean;
    60|  /** Commit + push + deploy to production (real mutation). */
    61|  approveGitDeploy: boolean;
    62|  validationMode: 'focused' | 'typecheck';
    63|  /** System bypass run (autonomous). Only set when role==='system'. */
    64|  systemMode: boolean;
    65|  /** Visible approval contract recorded for the audit trail (no secrets). */
    66|  ownerApprovedAction: IVXSeniorDeveloperApprovedActionContract | null;
    67|};
    68|
    69|export type IVXWorkerJob = {
    70|  jobId: string;
    71|  status: IVXWorkerJobStatus;
    72|  input: IVXWorkerJobInput;
    73|  createdAt: string;
    74|  startedAt: string | null;
    75|  finishedAt: string | null;
    76|  attempts: number;
    77|  /** Compact, secret-safe result summary once the job finishes. */
    78|  result: IVXWorkerJobResult | null;
    79|  error: string | null;
    80|};
    81|
    82|/** Secret-safe proof summary written to the durable ledger. */
    83|export type IVXWorkerJobResult = {
    84|  jobId: string;
    85|  goal: string;
    86|  ok: boolean;
    87|  endToEndProductionComplete: boolean;
    88|  changedFiles: string[];
    89|  testsRun: boolean;
    90|  testsPassed: boolean;
    91|  typecheckRun: boolean;
    92|  buildRun: boolean;
    93|  commitCreated: boolean;
    94|  commitSha: string | null;
    95|  commitUrl: string | null;
    96|  pushed: boolean;
    97|  branch: string | null;
    98|  deployId: string | null;
    99|  deployStatus: string | null;
   100|  deployVerified: boolean;
   101|  liveCommit: string | null;
   102|  commitMatch: boolean;
   103|  healthOk: boolean;
   104|  healthStatus: number | null;
   105|  versionEndpoint: string | null;
   106|  generatedFeatureSlug: string | null;
   107|  auditFiles: { json: string; jsonl: string };
   108|  finalStatus: 'COMPLETE' | 'LOCAL_ONLY' | 'BLOCKED' | 'FAILED';
   109|  error: string | null;
   110|  durable: boolean;
   111|  generatedAt: string;
   112|};
   113|
   114|type QueueDoc = {
   115|  marker: typeof IVX_SENIOR_DEV_WORKER_MARKER;
   116|  durable: boolean;
   117|  updatedAt: string;
   118|  jobs: IVXWorkerJob[];
   119|};
   120|
   121|type LedgerDoc = {
   122|  marker: typeof IVX_SENIOR_DEV_WORKER_MARKER;
   123|  durable: boolean;
   124|  updatedAt: string;
   125|  entries: IVXWorkerJobResult[];
   126|};
   127|
   128|function nowIso(): string {
   129|  return new Date().toISOString();
   130|}
   131|
   132|function emptyQueue(durable: boolean): QueueDoc {
   133|  return { marker: IVX_SENIOR_DEV_WORKER_MARKER, durable, updatedAt: nowIso(), jobs: [] };
   134|}
   135|
   136|function emptyLedger(durable: boolean): LedgerDoc {
   137|  return { marker: IVX_SENIOR_DEV_WORKER_MARKER, durable, updatedAt: nowIso(), entries: [] };
   138|}
   139|
   140|/**
   141| * In-memory mirror so the queue/worker keep functioning even when Supabase is
   142| * not configured (local dev / tests) and to avoid a read-modify-write race
   143| * between the enqueue call and the async drain.
   144| */
   145|let memoryQueue: QueueDoc | null = null;
   146|let memoryLedger: LedgerDoc | null = null;
   147|let draining = false;
   148|
   149|async function loadQueue(): Promise<QueueDoc> {
   150|  const durable = isDurableStoreConfigured();
   151|  if (!durable) {
   152|    if (!memoryQueue) memoryQueue = emptyQueue(false);
   153|    return memoryQueue;
   154|  }
   155|  try {
   156|    const doc = await readDurableJson<QueueDoc>(QUEUE_FILE, emptyQueue(true));
   157|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   158|  } catch {
   159|    if (!memoryQueue) memoryQueue = emptyQueue(false);
   160|    return memoryQueue;
   161|  }
   162|}
   163|
   164|async function saveQueue(doc: QueueDoc): Promise<void> {
   165|  const trimmed: QueueDoc = {
   166|    marker: IVX_SENIOR_DEV_WORKER_MARKER,
   167|    durable: doc.durable,
   168|    updatedAt: nowIso(),
   169|    jobs: doc.jobs.slice(-MAX_QUEUE_RETAINED),
   170|  };
   171|  memoryQueue = trimmed;
   172|  if (isDurableStoreConfigured()) {
   173|    try {
   174|      await writeDurableJson(QUEUE_FILE, trimmed);
   175|    } catch {
   176|      // Durable write failed — the in-memory mirror still keeps the worker alive.
   177|    }
   178|  }
   179|}
   180|
   181|async function loadLedger(): Promise<LedgerDoc> {
   182|  const durable = isDurableStoreConfigured();
   183|  if (!durable) {
   184|    if (memoryLedger && memoryLedger.entries.length > 0) return memoryLedger;
   185|    // Diskless restart fallback: recover the ledger persisted to the GitHub
   186|    // side branch so proof survives Render deploy restarts without Supabase.
   187|    const fromGitHub = await githubLedgerRead();
   188|    if (fromGitHub) {
   189|      memoryLedger = fromGitHub;
   190|      return fromGitHub;
   191|    }
   192|    if (!memoryLedger) memoryLedger = emptyLedger(false);
   193|    return memoryLedger;
   194|  }
   195|  try {
   196|    const doc = await readDurableJson<LedgerDoc>(LEDGER_FILE, emptyLedger(true));
   197|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   198|  } catch {
   199|    if (!memoryLedger) memoryLedger = emptyLedger(false);
   200|    return memoryLedger;
   201|  }
   202|}
   203|
   204|// ── GitHub side-branch ledger persistence (no Supabase service key needed) ──
   205|// The ledger is committed to a NON-deploy branch so Render autoDeploy (which
   206|// watches main) never fires from a ledger write. No secrets are stored.
   207|
   208|const LEDGER_GITHUB_BRANCH = 'ivx-proof-ledger';
   209|const DEFAULT_LEDGER_REPO = 'ibb142/rork-global-real-estate-invest';
   210|
   211|function ledgerGithubToken(): string {
   212|  return typeof process.env.GITHUB_TOKEN === 'string' ? process.env.GITHUB_TOKEN.trim() : '';
   213|}
   214|
   215|function ledgerGithubRepo(): string {
   216|  const raw = typeof process.env.GITHUB_REPO === 'string' ? process.env.GITHUB_REPO.trim() : '';
   217|  const match = raw.match(/([A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+?)(?:\.git)?$/);
   218|  if (match && match[1].includes('/')) return match[1];
   219|  return DEFAULT_LEDGER_REPO;
   220|}
   221|
   222|function ledgerGithubHeaders(): Record<string, string> {
   223|  return {
   224|    Authorization: `Bearer ${ledgerGithubToken()}`,
   225|    Accept: 'application/vnd.github+json',
   226|    'Content-Type': 'application/json',
   227|  };
   228|}
   229|
   230|async function githubLedgerRead(): Promise<LedgerDoc | null> {
   231|  const token = ledgerGithubToken();
   232|  if (!token) return null;
   233|  try {
   234|    const res = await fetch(
   235|      `https://api.github.com/repos/${ledgerGithubRepo()}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   236|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   237|    );
   238|    if (!res.ok) return null;
   239|    const data = await res.json() as { content?: string };
   240|    if (!data.content) return null;
   241|    const decoded = Buffer.from(data.content, 'base64').toString('utf8');
   242|    const doc = JSON.parse(decoded) as LedgerDoc;
   243|    if (!Array.isArray(doc.entries)) return null;
   244|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   245|  } catch {
   246|    return null;
   247|  }
   248|}
   249|
   250|async function githubEnsureLedgerBranch(): Promise<boolean> {
   251|  const repo = ledgerGithubRepo();
   252|  try {
   253|    const refRes = await fetch(
   254|      `https://api.github.com/repos/${repo}/git/ref/heads/${LEDGER_GITHUB_BRANCH}`,
   255|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   256|    );
   257|    if (refRes.ok) return true;
   258|    const mainRes = await fetch(
   259|      `https://api.github.com/repos/${repo}/git/ref/heads/main`,
   260|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   261|    );
   262|    if (!mainRes.ok) return false;
   263|    const mainData = await mainRes.json() as { object?: { sha?: string } };
   264|    const baseSha = mainData.object?.sha;
   265|    if (!baseSha) return false;
   266|    const createRes = await fetch(`https://api.github.com/repos/${repo}/git/refs`, {
   267|      method: 'POST',
   268|      headers: ledgerGithubHeaders(),
   269|      body: JSON.stringify({ ref: `refs/heads/${LEDGER_GITHUB_BRANCH}`, sha: baseSha }),
   270|      signal: AbortSignal.timeout(10000),
   271|    });
   272|    return createRes.ok;
   273|  } catch {
   274|    return false;
   275|  }
   276|}
   277|
   278|async function githubLedgerWrite(doc: LedgerDoc): Promise<boolean> {
   279|  const token = ledgerGithubToken();
   280|  if (!token) return false;
   281|  const repo = ledgerGithubRepo();
   282|  try {
   283|    if (!(await githubEnsureLedgerBranch())) return false;
   284|    let existingSha: string | undefined;
   285|    const currentRes = await fetch(
   286|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   287|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   288|    );
   289|    if (currentRes.ok) {
   290|      const current = await currentRes.json() as { sha?: string };
   291|      existingSha = current.sha;
   292|    }
   293|    const putRes = await fetch(
   294|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}`,
   295|      {
   296|        method: 'PUT',
   297|        headers: ledgerGithubHeaders(),
   298|        body: JSON.stringify({
   299|          message: `chore(ledger): proof ledger update ${nowIso()}`,
   300|          content: Buffer.from(JSON.stringify(doc, null, 2), 'utf8').toString('base64'),
   301|          branch: LEDGER_GITHUB_BRANCH,
   302|          ...(existingSha ? { sha: existingSha } : {}),
   303|        }),
   304|        signal: AbortSignal.timeout(15000),
   305|      },
   306|    );
   307|    return putRes.ok;
   308|  } catch {
   309|    return false;
   310|  }
   311|}
   312|
   313|async function appendLedger(result: IVXWorkerJobResult): Promise<void> {
   314|  const current = await loadLedger();
   315|  const entries = [result, ...current.entries.filter((e) => e.jobId !== result.jobId)].slice(0, MAX_LEDGER_RETAINED);
   316|  const doc: LedgerDoc = {
   317|    marker: IVX_SENIOR_DEV_WORKER_MARKER,
   318|    durable: isDurableStoreConfigured(),
   319|    updatedAt: nowIso(),
   320|    entries,
   321|  };
   322|  memoryLedger = doc;
   323|  if (isDurableStoreConfigured()) {
   324|    try {
   325|      await writeDurableJson(LEDGER_FILE, doc);
   326|      await appendDurableEvent(LEDGER_FILE, { type: 'proof_ledger_entry', ...result } as Record<string, unknown>);
   327|    } catch {
   328|      // Durable write failed — in-memory ledger still holds the entry.
   329|    }
   330|  } else {
   331|    // No Supabase service key in this runtime — persist to the GitHub side
   332|    // branch so proof survives Render's diskless deploy restarts.
   333|    await githubLedgerWrite({ ...doc, durable: true });
   334|  }
   335|}
   336|
   337|/**
   338| * Archive an externally-produced deployment proof (e.g. from the chat
   339| * deployment brain's /deploy-pipeline) into the same durable proof ledger the
   340| * worker writes, so /senior-proof and /senior-ledger surface it.
   341| */
   342|export async function archiveDeploymentProofToLedger(entry: IVXWorkerJobResult): Promise<boolean> {
   343|  try {
   344|    await appendLedger(entry);
   345|    return true;
   346|  } catch {
   347|    return false;
   348|  }
   349|}
   350|
   351|/**
   352| * Derive a secret-safe proof summary from a full senior-developer run proof and
   353| * the optional deploy-match verification.
   354| */
   355|export function summarizeProof(
   356|  jobId: string,
   357|  proof: IVXSeniorDeveloperRunProof,
   358|  match: Awaited<ReturnType<typeof verifyLiveCommitMatch>> | null,
   359|): IVXWorkerJobResult {
   360|  const validations = proof.validations;
   361|  const testValidation = validations.find((v) => /test|import-smoke/i.test(v.command)) ?? null;
   362|  const typecheckValidation = validations.find((v) => /tsc|typecheck|noEmit/i.test(v.command)) ?? null;
   363|  const commitSha = proof.gitDeployOperator.github.commitSha;
   364|  const commitCreated = Boolean(commitSha) && proof.gitDeployOperator.github.commitAttempted;
   365|  const deployId = proof.gitDeployOperator.render.deployId;
   366|  const deployStatus = proof.gitDeployOperator.render.deployStatus;
   367|  const healthOk = proof.productionVerification.ok;
   368|
   369|  const finalStatus: IVXWorkerJobResult['finalStatus'] = proof.endToEndProductionComplete
   370|    ? 'COMPLETE'
   371|    : proof.ok
   372|      ? 'LOCAL_ONLY'
   373|      : proof.gitDeployOperator.status === 'blocked_missing_credentials'
   374|        || proof.gitDeployOperator.status === 'ready_owner_approval_required'
   375|        ? 'BLOCKED'
   376|        : 'FAILED';
   377|
   378|  return {
   379|    jobId,
   380|    goal: proof.goal.slice(0, 280),
   381|    ok: proof.ok,
   382|    endToEndProductionComplete: proof.endToEndProductionComplete,
   383|    changedFiles: proof.changedFiles.slice(0, 25),
   384|    testsRun: testValidation !== null,
   385|    testsPassed: validations.length > 0 && validations.every((v) => v.ok),
   386|    typecheckRun: typecheckValidation !== null,
   387|    buildRun: validations.length > 0,
   388|    commitCreated,
   389|    commitSha,
   390|    commitUrl: proof.gitDeployOperator.github.commitUrl,
   391|    pushed: commitCreated,
   392|    branch: proof.gitDeployOperator.github.branch,
   393|    deployId,
   394|    deployStatus,
   395|    deployVerified: match?.match ?? false,
   396|    liveCommit: match?.liveCommit ?? null,
   397|    commitMatch: match?.match ?? false,
   398|    healthOk,
   399|    healthStatus: proof.productionVerification.httpStatus,
   400|    versionEndpoint: match?.versionEndpoint ?? null,
   401|    generatedFeatureSlug: proof.generatedFeature.feature?.slug ?? null,
   402|    auditFiles: proof.auditFiles,
   403|    finalStatus,
   404|    error: proof.ok ? null : (proof.gitDeployOperator.reason || proof.productionVerification.error || 'Run did not complete end-to-end.'),
   405|    durable: isDurableStoreConfigured(),
   406|    generatedAt: proof.generatedAt,
   407|  };
   408|}
   409|
   410|/**
   411| * Submit an owner-approved development task to the worker queue. The owner
   412| * approval MUST already be verified by the caller (API boundary). Returns the
   413| * created job; the worker drains the queue asynchronously.
   414| */
   415|export async function enqueueSeniorDeveloperJob(input: IVXWorkerJobInput): Promise<IVXWorkerJob> {
   416|  const goal = input.goal.trim();
   417|  if (!goal) throw new Error('A senior developer goal is required to enqueue a job.');
   418|  if (!input.ownerApproved) throw new Error('Cannot enqueue a senior developer job without verified owner approval.');
   419|
   420|  const job: IVXWorkerJob = {
   421|    jobId: `ivx-worker-${randomUUID()}`,
   422|    status: 'queued',
   423|    input: { ...input, goal },
   424|    createdAt: nowIso(),
   425|    startedAt: null,
   426|    finishedAt: null,
   427|    attempts: 0,
   428|    result: null,
   429|    error: null,
   430|  };
   431|
   432|  const queue = await loadQueue();
   433|  queue.jobs.push(job);
   434|  await saveQueue(queue);
   435|  appendDurableEvent(QUEUE_FILE, { type: 'job_enqueued', jobId: job.jobId, goal: goal.slice(0, 200) }).catch(() => {});
   436|
   437|  // Kick the worker without blocking the caller.
   438|  void drainSeniorDeveloperQueue();
   439|  return job;
   440|}
   441|
   442|/** Read one job by id (newest queue state). */
   443|export async function getSeniorDeveloperJob(jobId: string): Promise<IVXWorkerJob | null> {
   444|  const queue = await loadQueue();
   445|  return queue.jobs.find((j) => j.jobId === jobId) ?? null;
   446|}
   447|
   448|/** List recent jobs (newest first). */
   449|export async function listSeniorDeveloperJobs(limit: number = 25): Promise<IVXWorkerJob[]> {
   450|  const queue = await loadQueue();
   451|  const capped = Math.max(1, Math.min(MAX_QUEUE_RETAINED, Math.floor(limit)));
   452|  return [...queue.jobs].reverse().slice(0, capped);
   453|}
   454|
   455|/** Read the durable proof ledger (newest first). */
   456|export async function listSeniorDeveloperProofLedger(limit: number = 25): Promise<IVXWorkerJobResult[]> {
   457|  const ledger = await loadLedger();
   458|  const capped = Math.max(1, Math.min(MAX_LEDGER_RETAINED, Math.floor(limit)));
   459|  return ledger.entries.slice(0, capped);
   460|}
   461|
   462|/** Compact last-proof summary read directly from the durable worker ledger. */
   463|export type IVXWorkerLastProof = {
   464|  lastJobId: string | null;
   465|  lastCommitHash: string | null;
   466|  lastDeployId: string | null;
   467|  lastHealthStatus: number | null;
   468|  lastVersionMatch: boolean;
   469|  completedAt: string | null;
   470|};
   471|
   472|/**
   473| * Read the most recent proof entry directly from the worker ledger and project
   474| * it to the compact owner-facing shape. Returns nulls when the ledger is empty.
   475| */
   476|export async function getSeniorDeveloperLastProof(): Promise<IVXWorkerLastProof> {
   477|  const ledger = await loadLedger();
   478|  const latest = ledger.entries[0] ?? null;
   479|  if (!latest) {
   480|    return {
   481|      lastJobId: null,
   482|      lastCommitHash: null,
   483|      lastDeployId: null,
   484|      lastHealthStatus: null,
   485|      lastVersionMatch: false,
   486|      completedAt: null,
   487|    };
   488|  }
   489|  return {
   490|    lastJobId: latest.jobId,
   491|    lastCommitHash: latest.commitSha,
   492|    lastDeployId: latest.deployId,
   493|    lastHealthStatus: latest.healthStatus,
   494|    lastVersionMatch: latest.commitMatch,
   495|    completedAt: latest.generatedAt,
   496|  };
   497|}
   498|
   499|async function updateJob(jobId: string, patch: Partial<IVXWorkerJob>): Promise<void> {
   500|  const queue = await loadQueue();
   501|  const idx = queue.jobs.findIndex((j) => j.jobId === jobId);
   502|  if (idx < 0) return;
   503|  queue.jobs[idx] = { ...queue.jobs[idx], ...patch };
   504|  await saveQueue(queue);
   505|}
   506|
   507|/**
   508| * Run ONE queued job to completion through the real execution pipeline. Exposed
   509| * for explicit triggering and deterministic testing. Returns the result, or
   510| * null when there is no queued job.
   511| */
   512|export async function processNextSeniorDeveloperJob(): Promise<IVXWorkerJobResult | null> {
   513|  const queue = await loadQueue();
   514|  const job = queue.jobs.find((j) => j.status === 'queued');
   515|  if (!job) return null;
   516|
   517|  await updateJob(job.jobId, { status: 'running', startedAt: nowIso(), attempts: job.attempts + 1 });
   518|
   519|  try {
   520|    const proof = await runIVXSeniorDeveloperTask({
   521|      goal: job.input.goal,
   522|      approvePatch: job.input.approvePatch,
   523|      patchConfirmationText: job.input.approvePatch ? IVX_SAFE_PATCH_CONFIRM_TEXT : '',
   524|      approveGitDeploy: job.input.approveGitDeploy,
   525|      gitDeployConfirmationText: job.input.approveGitDeploy ? IVX_GIT_DEPLOY_CONFIRM_TEXT : '',
   526|      validationMode: job.input.validationMode,
   527|      ownerApprovedAction: job.input.ownerApprovedAction ?? undefined,
   528|      systemMode: job.input.systemMode,
   529|    });
   530|
   531|    // Deploy verification: if a commit landed, confirm production serves it.
   532|    let match: Awaited<ReturnType<typeof verifyLiveCommitMatch>> | null = null;
   533|    const commitSha = proof.gitDeployOperator.github.commitSha;
