   165|        status,
   166|        finishedAt: finishedAt.toISOString(),
   167|        durationMs: finishedAt.getTime() - new Date(existing.startedAt).getTime(),
   168|        detail: patch.detail ?? existing.detail,
   169|        proof: patch.proof ?? existing.proof,
   170|        error: patch.error ?? existing.error,
   171|      };
   172|      runs[index] = updated;
   173|      await ensureDir();
   174|      await appendFile(LOG_PATH, `${JSON.stringify({ at: updated.finishedAt, event: status, run: updated })}\n`, 'utf8');
