describe('per-owner single-flight queue', () => {
  test('rejects a job without verified owner approval', async () => {
    await expect(
      enqueueOrAttachSeniorDeveloperJob(makeInput({ ownerApproved: false })),
    ).rejects.toThrow(/owner approval/i);
